def evaluate(current_reputation, observation, my_history, round_num):
    # Decaying reputation: recent actions have more weight than old ones
    # Use a learning rate of 0.2 to blend new observation with old reputation
    alpha = 0.2
    if observation["action"] == "cooperate":
        new_rep = (1 - alpha) * current_reputation + alpha * 1.0
    else:
        new_rep = (1 - alpha) * current_reputation + alpha * (-1.0)
    # Clamp to allowed range [-1.0, 1.0]
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Use own cooperation history to adjust the threshold:
    # the more I have cooperated, the more lenient (lower threshold) I become
    if len(my_history) == 0:
        coop_rate = 0.0
    else:
        coop_count = sum(1 for act in my_history if act == "cooperate")
        coop_rate = coop_count / len(my_history)
    # Threshold moves from 0.0 (if never cooperated) to -0.5 (if always cooperated)
    threshold = 0.0 - 0.5 * coop_rate
    return recipient_reputation >= threshold
